#include "stdlib/blas/ext/base/ndarray/dwhere.h"
#include "stdlib/blas/ext/base/dwhere.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdbool.h>

/**
* Takes elements from one of two one-dimensional double-precision floating-point ndarrays depending on a condition.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional condition ndarray.
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dwhere( const struct ndarray *arrays[] ) {
	const struct ndarray *condition = arrays[ 0 ];
	const struct ndarray *x = arrays[ 1 ];
	const struct ndarray *y = arrays[ 2 ];
	const struct ndarray *out = arrays[ 3 ];

	const CBLAS_INT N = stdlib_ndarray_dimension( condition, 0 );
	const CBLAS_INT strideC = stdlib_ndarray_stride_elements( condition, 0 );
	const CBLAS_INT offsetC = stdlib_ndarray_offset_elements( condition );
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );
	const CBLAS_INT strideY = stdlib_ndarray_stride_elements( y, 0 );
	const CBLAS_INT offsetY = stdlib_ndarray_offset_elements( y );
	const CBLAS_INT strideOut = stdlib_ndarray_stride_elements( out, 0 );
	const CBLAS_INT offsetOut = stdlib_ndarray_offset_elements( out );

	const bool *dataC = (const bool *)stdlib_ndarray_data( condition );
	const double *dataX = (const double *)stdlib_ndarray_data( x );
	const double *dataY = (const double *)stdlib_ndarray_data( y );
	double *dataOut = (double *)stdlib_ndarray_data( out );
	API_SUFFIX(stdlib_strided_dwhere_ndarray)( N, dataC, strideC, offsetC, dataX, strideX, offsetX, dataY, strideY, offsetY, dataOut, strideOut, offsetOut );
}
